INSERT OR IGNORE INTO settings(key,value) VALUES ('golden:/tangier-day-trips/full-day-trip-to-tangier-from-tarifa-spain/','{"version": 1, "path": "/tangier-day-trips/full-day-trip-to-tangier-from-tarifa-spain/", "status": "REVIEW REQUIRED", "overview": [{"text": "The full-day trip to Tangier from Tarifa, Spain offers an excellent opportunity to learn about the enchanting culture of Morocco. Whether you are in Spain and want to opt for this unique day trip that will take you to another different world where the style of life has been preserved over time by its inhabitants; or you are already in Tangier and planning to experience the best of this mysterious destination, then Tangier Grand Tour is the one to vouch for.", "links": []}], "facts": [{"icon": "clock", "label": "Duration", "value": "Full day"}, {"icon": "users", "label": "Tour type", "value": "Private"}, {"icon": "map", "label": "Meeting point", "value": "Tangier port or city"}, {"icon": "ferry", "label": "Ferry tickets", "value": "Optional"}, {"icon": "language", "label": "Guide language", "value": "English"}, {"icon": "pin", "label": "Destination", "value": "Tangier"}], "highlights": [{"text": "Meet & greet at the port, hotel or wherever in Tangier", "links": []}, {"text": "Have a sightseeing tour around Tangier including the Cape Spartel & Hercules Caves", "links": []}, {"text": "Experience the camel ride", "links": []}, {"text": "Learn the rich history of Tangier", "links": []}, {"text": "Meet the local culture and lifestyle on their own terms", "links": []}, {"text": "Wander around the Kasbah & Medina", "links": []}, {"text": "Visit the Kasbah Museum and the American Legation", "links": []}, {"text": "Explore the Souks that is divided into sections", "links": []}, {"text": "Taste local food", "links": []}], "itineraryMode": "stop", "itinerary": [{"id": "stop-1", "type": "stop", "label": "Stop 1", "title": "Arrive in Tarifa Port", "location": "Tarifa Port", "description": [{"text": "Our today’s Tangier day trip from Tarifa consists of getting your ferry from Tarifa to Tangier and meeting with your expert local tour guide through his/her eyes you will discover what Tangier has to offer.", "links": [{"text": "ferry from Tarifa to Tangier", "href": "/morocco-travel-tips/how-to-get-to-tangier-from-tarifa/"}]}], "duration": "", "image": "", "lat": 36.0105, "lng": -5.6052, "mapOrder": 1, "admission": false, "meal": false, "transport": true, "note": ""}, {"id": "stop-2", "type": "stop", "label": "Stop 2", "title": "Meet your guide in Tangier", "location": "Tangier Ville port", "description": [{"text": "You will initially embark on an interesting sightseeing tour around the Ville Nouvelle (New Town) a magical city that was built by eight international powers when it was allocated as an International Zone.", "links": []}], "duration": "", "image": "", "lat": 35.7855, "lng": -5.8039, "mapOrder": 2, "admission": false, "meal": false, "transport": true, "note": ""}, {"id": "stop-3", "type": "stop", "label": "Stop 3", "title": "Sightseeing & Cape Spartel", "location": "Cape Spartel", "description": [{"text": "Your private full-day trip to Tangier from Tarifa will be initiated by a nice drive through the paved avenues and form an idea about the tolerance and peaceful existence by which the locals have been known throughout history to the extent that all religious buildings including Mosques, Cathedrals, and Synagogues have been constructed in almost the same quarter.", "links": []}, {"text": "You will continue on the track to the Moroccan promontory Cape Spartel through fancy villas, mansions, and palaces. It is believed that both the Mediterranean and the Atlantic Seas converge at this point and it is also the most North Western point of mainland Africa.", "links": [{"text": "Cape Spartel", "href": "https://en.wikipedia.org/wiki/Cape_Spartel"}]}], "duration": "", "image": "", "lat": 35.7906, "lng": -5.9237, "mapOrder": 3, "admission": false, "meal": false, "transport": true, "note": ""}, {"id": "stop-4", "type": "stop", "label": "Stop 4", "title": "Hercules Caves & the Atlantic coast", "location": "Hercules Caves", "description": [{"text": "You will have time for refreshment and for enjoying the view before continuing to the Neolithic Attraction of Hercules Caves. You may want to experience the camel ride on the sandy beach of Tangier.", "links": []}], "duration": "", "image": "", "lat": 35.7601, "lng": -5.9393, "mapOrder": 4, "admission": false, "meal": false, "transport": true, "note": ""}, {"id": "stop-5", "type": "stop", "label": "Stop 5", "title": "Explore the Kasbah", "location": "Tangier Kasbah", "description": [{"text": "Your full-day trip to Tangier from Spain will reward you with a purely cultural walking tour of the Kasbah which is located uphill. You will walk through its intricate alleyways to Dar El Makhzen which was resided by Sultans in the 16th century and has been transformed into a nice Museum exhibiting a good selection of antiquities and handmade Moroccan crafts.", "links": []}], "duration": "", "image": "", "lat": 35.7881, "lng": -5.8132, "mapOrder": 5, "admission": false, "meal": false, "transport": false, "note": ""}, {"id": "stop-6", "type": "stop", "label": "Stop 6", "title": "The Medina, souks & mint tea", "location": "Tangier Medina", "description": [{"text": "You will then get to the vibrant Medina where you will visit a local bakery and learn about the daily life activities of the locals. Visit the Souk or market which is divided into different sections including fish, vegetables, olives, meat, crafts, jewelry, and much more. Enjoy a nice mint tea in a local café while watching the passers-by.", "links": []}], "duration": "", "image": "", "lat": 35.7854, "lng": -5.8106, "mapOrder": 6, "admission": false, "meal": false, "transport": false, "note": ""}, {"id": "stop-7", "type": "stop", "label": "Stop 7", "title": "Return to the port or your chosen location", "location": "Tangier Ville port", "description": [{"text": "In the afternoon, your Morocco day trip from Tarifa will come to end and your private tour guide will escort you back to the port to get your ferry back to Spain or will drop you off at a location of your convenience.", "links": []}, {"text": "You may want to opt for our all-inclusive Day trip to Morocco from Spain to spare you the trouble and instead, you can only enjoy the Moroccan tour experience.", "links": [{"text": "Day trip to Morocco from Spain", "href": "https://www.tangierexcursions.com/day-trips/day-trip-to-morocco-from-spain/"}]}], "duration": "", "image": "", "lat": 35.7855, "lng": -5.8039, "mapOrder": 7, "admission": false, "meal": false, "transport": true, "note": ""}], "included": [{"text": "Meet & greet at the port of Tangier, hotel, or anywhere in the city of Tangier.", "links": []}, {"text": "English speaking private tour guide.", "links": []}, {"text": "A well-maintained transportation including fuel.", "links": []}, {"text": "Unique experiences", "links": []}, {"text": "Local taxes.", "links": []}], "excluded": [{"text": "Admission fees to sites and places of interest", "links": []}, {"text": "Tips when appropriate", "links": []}, {"text": "Extras", "links": []}], "optional": [{"text": "Round trip ferry tickets", "links": []}, {"text": "A camel ride experience by the sandy beach of the Atlantic", "links": []}, {"text": "Lunch & drinks", "links": []}, {"text": "Extra time", "links": []}], "before": [{"id": "info-1", "icon": "accessibility", "title": "Accessibility", "body": [{"text": "The day trip to Tangier from Tarifa, Spain is not suitable for wheelchair users as the Medina (old town).", "links": []}]}, {"id": "info-2", "icon": "info", "title": "Other experiences", "body": [{"text": "We invite you to take a look at the top-rated day trip to Morocco from Spain or the Tangier guided walking tour .", "links": [{"text": "day trip to Morocco from Spain", "href": "https://www.tangierexcursions.com/day-trips/day-trip-to-morocco-from-spain/"}, {"text": "Tangier guided walking tour", "href": "https://www.tangierexcursions.com/day-trips/tangier-guided-walking-tour/"}]}]}, {"id": "info-3", "icon": "info", "title": "Ferry confirmation", "body": [{"text": "Please note that once you submit your booking form, we will subsequently send you the confirmation file displaying further travel tips on how to get to Tangier by ferry from Tarifa along with your round trip ferry tickets (if you go with the option of buying the ferry tickets through us).", "links": []}]}, {"id": "info-4", "icon": "info", "title": "Meeting your guide", "body": [{"text": "Please note that your private tour guide will be waiting for you at the Tangier Ville port’s terminal holding a signboard with your name on it. In case you can’t find your guide, you might get approached by other fellow tour guides, as a result,  please try to avoid them and immediately reach out to us at +212 666-941294 and we will effectively remedy any issue.", "links": [{"text": "+212 666-941294", "href": "tel:+212666941294"}]}]}], "cancellation": {"mode": "custom", "body": []}, "faqs": [{"id": "faq-1", "question": "How far is Morocco from Spain?", "answer": [{"text": "Morocco is the closest point to the African continent from Spain and Europe. The distance between Tangier (in the north of Morocco) and Tarifa (in the south of Spain) is around 15 kms (9.32 miles).", "links": []}]}, {"id": "faq-2", "question": "How long is the ferry ride from Tarifa to Tangier?", "answer": [{"text": "Normally, it takes around an hour including the customs.", "links": []}]}, {"id": "faq-3", "question": "Do you offer shared tours?", "answer": [{"text": "Since the foundation of Tangier Excursions LLC back in 2015, our commitment to offering, quality services while allowing our dear customers experience Tangier and Morocco intimately, has been always the same. Our aim can be attained through private tours..", "links": []}]}], "reusableIds": [], "reviews": [{"id": "legacy-1", "title": "Great Tour!", "text": "Mohammed gave us a great tour around Tangier. He was knowledgeable and customized the tour to our interests. His English was excellent as well. The driver was very safe and courteous. He realized we were Jewish and made sure that we got to see the beautiful synagogues in the area. That was very special. We particularly enjoyed seeing the kindness to animals and tolerance of all religious there. My only complaint is that we didn’t have any menu items to choose from for lunch. As we did request, spicy Moroccan food on our form, needless to say, the CousCous was delicious. Would highly recommend!", "name": "Laurel W", "date": "November 26, 2024", "country": "", "rating": null, "verified": false, "source": "Published website review"}, {"id": "legacy-2", "title": "Great Personal Service", "text": "We were met by Mohamed as we got off the ferry from Tarifa and escorted to a van with a driver. This was great because it enabled Mohamed to focus his attention on introducing us to Tangier. Mohamed pointed out some of the luxury celebrity housing on our way to our camel ride. It’;s a very touristy thing to do but I’m very glad I did it. It’s very different from riding a horse and the experience of the camel getting to its feet and then later getting back down is special. We were taken to breakfast where we had mint tea and camel cheese on some very good bread. Camel cheese is quite mild and very good. Mohamed gave us a thorough tour in the time we had. When it was time to go he escorted us through customs to the front of the ferry line. We were the first ones on for the return trip. April 2023", "name": "Jack Cannata", "date": "May 8, 2023", "country": "", "rating": null, "verified": false, "source": "Published website review"}, {"id": "legacy-3", "title": "Absolutely fantastic!", "text": "We contacted Tangier Excursions after deciding we’d like to try an overnight stay in Morocco whilst on holiday in Spain. Moha responded immediately giving us loads of confidence, recommending what we should do and then very swiftly organised absolutely everything for us. We were met by a driver in a very smart Mercedes van at Tangier port, tour guides showed us around and we had a wonderful overnight stay in the blue city of Chechaouen. An amazing experience and so straight forward thanks to Moha! I’d highly recommend Tangier Excursions.", "name": "CJ Neale", "date": "October 18, 2022", "country": "", "rating": null, "verified": false, "source": "Published website review"}, {"id": "legacy-4", "title": "Wonderful Experience", "text": "Tangier Excursions is the consummate professional tour operator. Moha was very prompt, responding to all emails and taking care of the ferry tickets from Tarifa, and had a car waiting when we arrived, making everything simple. For the day-long tour, our guide was Mohamed and the gentleman was very friendly and extremely knowledgeable about the history of the country. We did a car tour in the morning (very nice) and a walking tour around the city in the afternoon. There were various stops for food and drinks, all of which were quite good. For first-time visitors to Morocco like ourselves, it opened our eyes to the beauty of the area. Thank you Moha! We will be back in Morocco some time again!.", "name": "Eric Smith", "date": "February 2, 2022", "country": "Australia", "rating": null, "verified": false, "source": "Published website review"}], "links": [{"text": "Google reviews", "href": "https://www.google.com/search?q=Tangier+Excursions+%26+Private+Tours&stick=H4sIAAAAAAAAAONgU1IxqEgxSLIwNEwxM0tLNUgztbQyqDC0ME61NDE3MDVJNDFMSkpdxKoUkpiXnplapOBakVxaVJyZn1esoKYQUJRZlliSqhCSDxQDAO0NSiBNAAAA&hl=en-GB&mat=CV8HFpVB6xoMEmYB5zj54W0rLpDeMyzP3CbyhP_cpaMLkatCp3FQVruqa3sxd9LlW9J-ZnytIQkCmYztrSW6TTxz4IcmZ5K1ojny9W_nnJF_5LDaoTMOcdhikkS5IbIOMWsC5WoN3oTlsekd0ugMp0s&authuser=0#lrd=0xd0b811d66fe0f59:0x183e947054a41bbe,1,,,"}, {"text": "Tripadvisor reviews", "href": "https://www.tripadvisor.com/Attraction_Review-g293737-d9597336-Reviews-Tangier_Excursions-Tangier_Tanger_Tetouan_Al_Hoceima.html"}, {"text": "Trustpilot reviews", "href": "https://www.trustpilot.com/review/tangierexcursions.com"}, {"text": "ferry from Tarifa to Tangier", "href": "/morocco-travel-tips/how-to-get-to-tangier-from-tarifa/"}, {"text": "Cape Spartel", "href": "https://en.wikipedia.org/wiki/Cape_Spartel"}, {"text": "Day trip to Morocco from Spain", "href": "https://www.tangierexcursions.com/day-trips/day-trip-to-morocco-from-spain/"}, {"text": "Tangier guided walking tour", "href": "https://www.tangierexcursions.com/day-trips/tangier-guided-walking-tour/"}, {"text": "+212 666-941294", "href": "tel:+212666941294"}, {"text": "Details..", "href": "https://www.tangierexcursions.com/day-trips/day-trip-to-tangier-and-tetouan-from-gibraltar/"}, {"text": "Details..", "href": "https://www.tangierexcursions.com/day-trips/tangier-to-chefchaouen-day-trip/"}], "sectionOrder": ["overview", "reviews", "highlights", "itinerary", "included", "map", "cancellation", "before", "faqs"], "map": {"enabled": true, "pointsReviewed": false}, "migration": {"sourceHash": "1258f7cb93247fc68a992fae136bbd494b3d195a0fe9a33b9a6b914b44a47365", "sourcePath": "data/catalog.json", "segments": [{"id": "source-1", "field": "overview", "text": "The full-day trip to Tangier from Tarifa, Spain offers an excellent opportunity to learn about the enchanting culture of Morocco. Whether you are in Spain and want to opt for this unique day trip that will take you to another different world where the style of life has been preserved over time by its inhabitants; or you are already in Tangier and planning to experience the best of this mysterious destination, then Tangier Grand Tour is the one to vouch for.", "links": []}, {"id": "source-2", "field": "highlights", "text": "Meet & greet at the port, hotel or wherever in Tangier", "links": []}, {"id": "source-3", "field": "highlights", "text": "Have a sightseeing tour around Tangier including the Cape Spartel & Hercul